    cin.tie(nullptr);

    int n;
    cin >> n;

    Point hero, demon;
    cin >> hero.x >> hero.y;
    cin >> demon.x >> demon.y;

    vector<Point> crystals(n);
    for (int i = 0; i < n; i++) {
        cin >> crystals[i].x >> crystals[i].y;
    }

    // Time when miasma reaches each crystal from demon lord
    vector<double> crystalMiasmaTime(n);
    for (int i = 0; i < n; i++) {
        crystalMiasmaTime[i] = dist(demon, crystals[i]);
    }

    // dp[mask][last] = earliest time hero can be at crystal 'last' having collected mask
    const double INF = 1e18;
    vector<vector<double>> dp(1 << n, vector<double>(n, INF));

    // Initialize: starting from hero to each crystal
    for (int i = 0; i < n; i++) {
        double travelTime = dist(hero, crystals[i]);
        if (travelTime < crystalMiasmaTime[i]) {
            dp[1 << i][i] = travelTime;
        }
    }

    // DP over subsets
    for (int mask = 1; mask < (1 << n); mask++) {
        for (int last = 0; last < n; last++) {
            if (!(mask & (1 << last))) continue;
            if (dp[mask][last] == INF) continue;
            for (int nxt = 0; nxt < n; nxt++) {
                if (mask & (1 << nxt)) continue;
                double arrival = dp[mask][last] + dist(crystals[last], crystals[nxt]);
