struct Point {
    double x, y;
};

static double dist(const Point& a, const Point& b) {
    double dx = a.x - b.x, dy = a.y - b.y;
    return sqrt(dx * dx + dy * dy);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    Point hero, demon;
    cin >> hero.x >> hero.y;
    cin >> demon.x >> demon.y;

    vector<Point> c(n);
    for (int i = 0; i < n; ++i) cin >> c[i].x >> c[i].y;

    // Time limit to stand on crystal i:
    // must arrive strictly before the miasma reaches it.
    // Since both hero and miasma move at speed 1,
    // deadline[i] = distance(demon, crystal_i).
    vector<double> deadline(n);
    for (int i = 0; i < n; ++i) deadline[i] = dist(demon, c[i]);

    // DP over subsets:
    // dp[mask][i] = minimum time to collect exactly crystals in mask
    // and finish at crystal i (where i is in mask).
    const double INF = 1e100;
    int N = 1 << n;
    vector<vector<double>> dp(N, vector<double>(n, INF));

    for (int i = 0; i < n; ++i) {
        double t = dist(hero, c[i]);
        if (t + 1e-12 < deadline[i]) {
            dp[1 << i][i] = t;
        }
    }

    for (int mask = 0; mask < N; ++mask) {
        for (int last = 0; last < n; ++last) {
            double cur = dp[mask][last];
            if (cur >= INF / 2) continue;

            for (int nxt = 0; nxt < n; ++nxt) {
                if (mask & (1 << nxt)) continue;
                double nt = cur + dist(c[last], c[nxt]);
                if (nt + 1e-12 < deadline[nxt]) {
                    int nmask = mask | (1 << nxt);
                    if (nt < dp[nmask][nxt]) dp[nmask][nxt] = nt;
                }
            }
        }
    }

    int full = N - 1;
    bool ok = (n == 0);
    for (int i = 0; i < n; ++i) {
        if (dp[full][i] < INF / 2) ok = true;
    }

    cout << (ok ? "YES" : "NO") << '\n';
    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]); // number of crystals

        // Read hero start
        parts = br.readLine().split(" ");
        double hx = Double.parseDouble(parts[0]);
        double hy = Double.parseDouble(parts[1]);

        // Read demon lord
        parts = br.readLine().split(" ");
        double dx = Double.parseDouble(parts[0]);
        double dy = Double.parseDouble(parts[1]);

        double[] cx = new double[n];
        double[] cy = new double[n];
        for (int i = 0; i < n; i++) {
            parts = br.readLine().split(" ");
            cx[i] = Double.parseDouble(parts[0]);
            cy[i] = Double.parseDouble(parts[1]);
        }

        // Precompute distances
        // distHero[i] = distance from hero to crystal i
        double[] distHero = new double[n];
        // distDemon[i] = distance from demon lord to crystal i
        double[] distDemon = new double[n];
        for (int i = 0; i < n; i++) {
            distHero[i] = Math.hypot(cx[i] - hx, cy[i] - hy);
            distDemon[i] = Math.hypot(cx[i] - dx, cy[i] - dy);
        }

        // Check if any crystal is already unreachable (demon reaches before hero)
        for (int i = 0; i < n; i++) {
            // Hero must reach before demon (strictly less, because boundary is forbidden)
            if (distHero[i] >= distDemon[i]) {
                System.out.println("NO");
                return;
            }
        }

        // Now we need to check if there's an ordering to collect all crystals
        // We'll use a DP over subsets: dp[mask] = minimum time to collect set 'mask' and end at some crystal
        // But we also need ending position info. dp[mask][last] = min time to collect mask ending at last
        int N = n;
        double[][] dp = new double[1 << N][N];
        for (int mask = 0; mask < (1 << N); mask++) {
            Arrays.fill(dp[mask], Double.MAX_VALUE);
        }

        // Initialize with single crystals
        for (int i = 0; i < N; i++) {
            dp[1 << i][i] = distHero[i];
        }

        // Precompute distances between crystals
        double[][] distBetween = new double[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                distBetween[i][j] = Math.hypot(cx[i] - cx[j], cy[i] - cy[j]);
            }
        }

        // DP
        for (int mask = 1; mask < (1 << N); mask++) {
            for (int last = 0; last < N; last++) {
                if (dp[mask][last] == Double.MAX_VALUE) continue;
                double timeSoFar = dp[mask][last];
                // Try to go to next crystal
                for (int next = 0; next < N; next++) {
                    if ((mask & (1 << next)) != 0) continue;
                    int newMask = mask | (1 << next);
                    double travelTime = distBetween[last][next];
                    double arrivalTime = timeSoFar + travelTime;
                    // Check if demon reaches next before hero
                    if (arrivalTime >= distDemon[next]) {
                        continue; // cannot collect
                    }
                    if (arrivalTime < dp[newMask][next]) {
                        dp[newMask][next] = arrivalTime;
                    }
                }
            }
        }

        // Check if any full mask is reachable
        int fullMask = (1 << N) - 1;
        for (int last = 0; last < N; last++) {
            if (dp[fullMask][last] < Double.MAX_VALUE) {
                System.out.println("YES");
                return;
            }
        }
        System.out.println("NO");
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double hx = sc.nextDouble(), hy = sc.nextDouble();
        double dx = sc.nextDouble(), dy = sc.nextDouble();
        int n = sc.nextInt();
        double[] cx = new double[n], cy = new double[n];
        for (int i = 0; i < n; i++) {
            cx[i] = sc.nextDouble();
            cy[i] = sc.nextDouble();
        }

        // dist from demon to each crystal
        double[] demonDist = new double[n];
        for (int i = 0; i < n; i++) {
            demonDist[i] = Math.sqrt((cx[i]-dx)*(cx[i]-dx) + (cy[i]-dy)*(cy[i]-dy));
        }

        // dist between crystals
        double[][] cdist = new double[n][n];
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                cdist[i][j] = Math.sqrt((cx[i]-cx[j])*(cx[i]-cx[j]) + (cy[i]-cy[j])*(cy[i]-cy[j]));

        // dist from hero to each crystal
        double[] hdist = new double[n];
        for (int i = 0; i < n; i++)
            hdist[i] = Math.sqrt((cx[i]-hx)*(cx[i]-hx) + (cy[i]-hy)*(cy[i]-hy));

        // dp[mask][i] = min time to collect crystals in mask, last at crystal i
        double[][] dp = new double[1<<n][n];
        for (double[] row : dp) Arrays.fill(row, Double.MAX_VALUE);

        // Initialize: hero goes directly to crystal i first
        for (int i = 0; i < n; i++) {
            double t = hdist[i];
            if (t < demonDist[i] - 1e-9) {
                dp[1<<i][i] = t;
            }
        }

        // Fill DP
        for (int mask = 1; mask < (1<<n); mask++) {
            for (int i = 0; i < n; i++) {
                if (dp[mask][i] == Double.MAX_VALUE) continue;
                if ((mask & (1<<i)) == 0) continue;
                for (int j = 0; j < n; j++) {
                    if ((mask & (1<<j)) != 0) continue;
                    double t = dp[mask][i] + cdist[i][j];
                    if (t < demonDist[j] - 1e-9) {
                        int nmask = mask | (1<<j);
                        if (t < dp[nmask][j]) dp[nmask][j] = t;
                    }
                }
            }
        }

        int full = (1<<n) - 1;
        boolean ok = false;
        for (int i = 0; i < n; i++) {
            if (dp[full][i] < Double.MAX_VALUE) { ok = true; break; }
        }
        if (n == 0) ok = true;

        System.out.println(ok ? "Yes" : "No");
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Point {
        long x, y;
        Point(long x, long y) {
            this.x = x;
            this.y = y;
        }
    }

    static long dist2(Point a, Point b) {
        long dx = a.x - b.x;
        long dy = a.y - b.y;
        return dx * dx + dy * dy;
    }

    static boolean canReach(Point from, Point to, Point demon) {
        // Need:
        // current_time + |from-to| < |to-demon|
        // If from is reachable at earliest time = |from-hero_start|,
        // and edges satisfy |from-to| < |to-demon| - |from-demon|,
        // then chaining works.
        //
        // We use squared comparison:
        // |from-to| < |to-demon| - |from-demon|
        // equivalent to |from-to| + |from-demon| < |to-demon|
        //
        // Compare by doubles safely enough for geometry with integer coords.
        double a = Math.sqrt(dist2(from, to));
        double b = Math.sqrt(dist2(from, demon));
        double c = Math.sqrt(dist2(to, demon));
        return a + b < c - 1e-12;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt();
        Point hero = new Point(fs.nextLong(), fs.nextLong());
        Point demon = new Point(fs.nextLong(), fs.nextLong());

        Point[] crystal = new Point[n];
        for (int i = 0; i < n; i++) {
            crystal[i] = new Point(fs.nextLong(), fs.nextLong());
        }

        // A crystal can be collected directly from the start iff
        // distance(hero, c) < distance(demon, c)
        // More generally, from point A already collected at earliest time dist(hero,A),
        // can move to B iff dist(A,B) < dist(demon,B) - dist(demon,A),
        // which by triangle inequality happens exactly when demon, A, B are collinear
        // with A between demon and B. So reachable crystals are exactly those lying on
        // rays from the demon, and can be collected in increasing distance from demon,
        // starting from any crystal closer to hero than to demon.
        //
        // Thus we group crystals by direction from demon.

        HashMap<String, ArrayList<Long>> groups = new HashMap<>();
        HashSet<String> startable = new HashSet<>();

        for (int i = 0; i < n; i++) {
            long dx = crystal[i].x - demon.x;
            long dy = crystal[i].y - demon.y;

            long g = gcd(Math.abs(dx), Math.abs(dy));
            long ndx = dx / g;
            long ndy = dy / g;
            String key = ndx + "," + ndy;

            groups.computeIfAbsent(key, k -> new ArrayList<>()).add(dist2(demon, crystal[i]));

            if (dist2(hero, crystal[i]) < dist2(demon, crystal[i])) {
                startable.add(key);
            }
        }

        for (String key : groups.keySet()) {
            if (!startable.contains(key)) {
                System.out.println("NO");
                return;
            }
        }

        System.out.println("YES");
    }

    static long gcd(long a, long b) {
        while (b != 0) {
            long t = a % b;
            a = b;
            b = t;
        }
        return a;
    }
}

