#include <stdio.h>
#include <math.h>

#define MAX_N 100000

typedef struct {
    double x, y;
} Point;

// distance squared (to avoid sqrt when possible)
double dist2(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return dx*dx + dy*dy;
}

// distance
double dist(Point a, Point b) {
    return sqrt(dist2(a, b));
}

int main() {
    int n;
    Point hero, demon;
    Point crystals[MAX_N];

    scanf("%lf %lf", &hero.x, &hero.y);
    scanf("%lf %lf", &demon.x, &demon.y);
    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &crystals[i].x, &crystals[i].y);
    }

    // If no crystals, hero wins immediately
    if (n == 0) {
        printf("YES\n");
        return 0;
    }

    // For each crystal, compute the time the hero can reach it and the time the miasma reaches it
    // The hero must reach each crystal strictly before the miasma reaches it.
    // The hero can collect crystals in any order, so we need to see if there's a feasible order.
    // This is equivalent to checking if for every crystal, dist(hero, crystal) < dist(demon, crystal).
    // Because the hero can go directly to each crystal one by one, and the miasma expands from demon.
    // However, if the hero goes to one crystal first, the miasma expands, possibly blocking later crystals.
    // The optimal strategy is to collect the "closest" (in terms of hero distance) crystals first.
    // Actually, the condition for possibility is that the hero can collect all crystals before any crystal is overtaken by miasma.
    // Since miasma expands uniformly, the hero should collect crystals in increasing order of distance from demon.
    // But we also need to account for travel time between crystals.
    // This becomes a traveling salesman problem with time constraints, which is NP-hard in general.
    // However, the problem likely expects a simpler condition: 
    // The hero can collect all crystals if and only if for every crystal, the hero is closer to it than the demon is.
    // Because the hero can go directly to each crystal from start, and then to the next, etc.
    // But if hero goes to a far crystal first, the miasma may cover a closer crystal later.
    // Actually, the hero can always go to the crystal that is closest to demon first, then the next, etc.
    // The condition dist(hero, crystal) < dist(demon, crystal) for all crystals is necessary but not sufficient.
    // Consider hero at (0,0), demon at (10,0), crystals at (5,0) and (6,0). 
    // Hero distances: 5 and 6; demon distances: 5 and 4. For second crystal, 6 < 4? No. So fails.
    // But what about hero at (0,0), demon at (5,0), crystals at (2,0) and (3,0)?
    // Hero: 2 and 3; demon: 3 and 2. For crystal at 2: 2<3 ok; for crystal at 3: 3<2? No.
    // So hero cannot get the second one because demon is closer.
    // Another example: hero at (0,0), demon at (10,0), crystals at (4,0) and (8,0).
    // Hero: 4 and 8; demon: 6 and 2. For first: 4<6 ok; second: 8<2? No. So fails.
    // But what if hero at (0,0), demon at (10,0), crystals at (1,0) and (9,0)?
    // Hero: 1 and 9; demon: 9 and 1. For first: 1<9 ok; second: 9<1? No.
    // So the condition seems necessary and also sufficient if we collect in order of demon distance?
    // Actually, consider hero at (0,0), demon at (0,10), crystals at (0,1), (0,2), (0,3).
    // Hero distances: 1,2,3; demon distances: 9,8,7. All hero < demon. Hero can go 0->1->2->3, total time = 3, miasma at time 3 reaches distance 3 from demon, so crystal at 3 is at distance 7 from demon, safe. So works.
    // Consider hero at (0,0), demon at (0,5), crystals at (0,2), (0,4). Hero: 2,4; demon: 3,1. For first: 2<3 ok; second: 4<1? No. So fails.
    // Consider hero at (0,0), demon at (3,0), crystal at (2,0). Hero:2, demon:1 -> 2<1? No, fails. So hero cannot get it.
    // Consider hero at (0,0), demon at (5,0), crystals at (1,0) and (4,0). Hero:1,4; demon:4,1. First:1<4 ok; second:4<1? No. So fails.
    // What about a case where all hero distances are less than demon distances, but the order makes it impossible?
    // Suppose hero at (0,0), demon at (10,0), crystals at (1,0) and (9.5,0). Hero:1 and 9.5; demon:9 and 0.5. For second: 9.5 < 0.5? No.
    // So condition fails.
    // Try to construct: hero at (0,0), demon at (10,0), crystals at (6,0) and (7,0). Hero:6,7; demon:4,3. Both hero > demon.
    // So fails.
    // It seems that if for all crystals, hero distance < demon distance, then the hero can collect them in order of increasing demon distance (which is decreasing hero distance? Actually demon distance increases as we go away from demon).
    // The worst case is the crystal farthest from demon (closest to hero). The hero goes there first? No, the hero should go to the crystal closest to demon first because it will be overtaken first.
    // So sort crystals by distance from demon ascending. Then simulate: start at hero, go to each in that order, check if arrival time < demon distance at that crystal.
    // This is a greedy algorithm that should work because the miasma expands uniformly.
    // Let's test: hero (0,0), demon (10,0), crystals at (2,0) and (8,0). Demon distances: 8 and 2. Sort: crystal at 8 (dist 2 from demon) first, then crystal at 2 (dist 8). 
    // Hero to first: distance 8, time 8, demon distance 2 -> 8 < 2? No. So fails. But is it actually impossible? Hero can go to crystal at 2 first: time 2, demon distance 8 -> 2<8 ok. Then from there to crystal at 8: distance 6, total time 8, demon distance from crystal at 8 is 2 -> 8<2? No. So fails anyway.
    // So the greedy works.
    // Another test: hero (0,0), demon (0,10), crystals at (0,1), (0,9). Demon distances: 9 and 1. Sort: crystal at 9 first (dist 1 from demon). Hero to there: dist 9, time 9, demon dist 1 -> 9<1? No. But if hero goes to (0,1) first: time 1, demon dist 9 -> ok, then to (0,9): dist 8, total time 9, demon dist 1 -> 9<1? No. So fails. Indeed, hero cannot get both because the far one is too close to demon.
    // So the greedy algorithm of sorting by demon distance and checking if arrival time < demon distance for each should determine feasibility.
    // But is it always optimal? Consider a case where going in a different order might allow both. Suppose hero close to demon but crystals are in a line. The greedy picks the one closest to demon first. If that fails, any order will fail because that crystal will be overtaken first. If it succeeds, then the hero can proceed. This is similar to scheduling with deadlines.
    // So algorithm: sort crystals by distance from demon ascending. Current time = 0, current position = hero. For each crystal in order:
    //   travel time = dist(current, crystal)
    //   arrival time = current time + travel time
    //   if arrival time >= dist(demon, crystal) then impossible.
    //   else current time = arrival time, current position = crystal.
    // If all pass, YES else NO.

    // First, check the simple necessary condition: for each crystal, dist(hero, crystal) < dist(demon, crystal)
    // If any fails, immediate NO (because even if hero goes directly there first, it's already too late or equal).
    // Actually, if dist(hero, crystal) >= dist(demon, crystal), then even if hero goes straight there, miasma reaches at same time or earlier, so cannot collect. So necessary.
    for (int i = 0; i < n; i++) {
        if (dist(hero, crystals[i]) >= dist(demon, crystals[i])) {
            printf("NO\n");
            return 0;
        }
    }

    // Now sort crystals by distance from demon
    // We'll use a simple O(n^2) selection sort since n <= 100000 might be too large, but we can use qsort.
    // Let's implement a struct with distance and index.
    typedef struct {
        double demonDist;
        Point p;
    } CrystalInfo;

    CrystalInfo infos[MAX_N];
    for (int i = 0; i < n; i++) {
        infos[i].demonDist = dist(demon, crystals[i]);
        infos[i].p = crystals[i];
    }

    // qsort
    int compare(const void *a, const void *b) {
        double da = ((CrystalInfo*)a)->demonDist;
        double db = ((CrystalInfo*)b)->demonDist;
        if (da < db) return -1;
        if (da > db) return 1;
        return 0;
    }

    qsort(infos, n, sizeof(CrystalInfo), compare);

    double current_time = 0.0;
    Point current_pos = hero;

    for (int i = 0; i < n; i++) {
        double travel = dist(current_pos, infos[i].p);
        double arrival = current_time + travel;
        if (arrival >= infos[i].demonDist) {
            printf("NO\n");
            return 0;
        }
        current_time = arrival;
        current_pos = infos[i].p;
    }

    printf("YES\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <math.h>

typedef struct {
    double x, y;
} Point;

static double dist2(Point a, Point b) {
    double dx = a.x - b.x;
    double dy = a.y - b.y;
    return dx * dx + dy * dy;
}

static int cmp_double(const void *a, const void *b) {
    double x = *(const double *)a;
    double y = *(const double *)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    Point hero, demon;
    scanf("%lf %lf", &hero.x, &hero.y);
    scanf("%lf %lf", &demon.x, &demon.y);

    Point *c = (Point *)malloc(sizeof(Point) * n);
    for (int i = 0; i < n; i++) {
        scanf("%lf %lf", &c[i].x, &c[i].y);
    }

    if (n == 0) {
        printf("Yes\n");
        free(c);
        return 0;
    }

    /*
      Let t be time.
      Hero can be at crystal i by time t iff:
        dist(hero, i) <= t
      Crystal i is still collectible at time t iff:
        dist(demon, i) > t   (boundary is forbidden too)

      So crystal i can be collected at all iff:
        dist(hero, i) < dist(demon, i)

      More generally, after collecting some crystals, movement between crystals
      also takes time. Since both hero and miasma expand at the same speed,
      the condition for moving from point A to crystal B before it is engulfed is:
        arrival_time_at_A + dist(A,B) < dist(demon,B)

      Define deadline(B) = dist(demon,B).
      This is a scheduling/path feasibility problem.

      A key observation:
      If we sort crystals by increasing deadline, then collecting all is possible
      iff repeatedly taking the earliest-deadline reachable crystal is possible.
      This follows from standard exchange argument for unit-speed travel with
      absolute deadlines under metric travel times from current position among
      already chosen points.

      We simulate greedily:
      current position starts at hero, current time = 0.
      Repeatedly choose among remaining crystals the one with smallest deadline
      that is still feasible now; equivalently after sorting by deadline, we must
      be able to visit them in that order.
    */

    double *deadline = (double *)malloc(sizeof(double) * n);
    int *idx = (int *)malloc(sizeof(int) * n);

    for (int i = 0; i < n; i++) {
        deadline[i] = sqrt(dist2(demon, c[i]));
        idx[i] = i;
    }

    /* sort indices by deadline */
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            if (deadline[idx[i]] > deadline[idx[j]]) {
                int tmp = idx[i];
                idx[i] = idx[j];
                idx[j] = tmp;
            }
        }
    }

    Point cur = hero;
    double time = 0.0;
    const double EPS = 1e-12;

    for (int k = 0; k < n; k++) {
        int i = idx[k];
        time += sqrt(dist2(cur, c[i]));
        if (!(time + EPS < deadline[i])) {
            printf("No\n");
            free(c);
            free(deadline);
            free(idx);
            return 0;
        }
        cur = c[i];
    }

    printf("Yes\n");

    free(c);
    free(deadline);
    free(idx);
    return 0;
}

import sys
from itertools import permutations
import math

def solve():
    input_data = sys.stdin.read().split()
    idx = 0

    # Read hero position
    hx, hy = float(input_data[idx]), float(input_data[idx+1]); idx += 2
    # Read demon lord position
    dx, dy = float(input_data[idx]), float(input_data[idx+1]); idx += 2
    # Read number of crystals
    n = int(input_data[idx]); idx += 1
    crystals = []
    for _ in range(n):
        cx, cy = float(input_data[idx]), float(input_data[idx+1]); idx += 2
        crystals.append((cx, cy))

    def dist(p1, p2):
        return math.sqrt((p1[0]-p2[0])**2 + (p1[1]-p2[1])**2)

    hero = (hx, hy)
    demon = (dx, dy)

    if n == 0:
        print("Yes")
        return

    INF = float('inf')
    # dp[mask][i] = min time to collect crystals in mask, ending at crystal i
    dp = [[INF] * n for _ in range(1 << n)]

    for i in range(n):
        t = dist(hero, crystals[i])
        if t < dist(demon, crystals[i]):
            dp[1 << i][i] = t

    for mask in range(1, 1 << n):
        for i in range(n):
            if dp[mask][i] == INF:
                continue
            if not (mask >> i & 1):
                continue
            for j in range(n):
                if mask >> j & 1:
                    continue
                new_mask = mask | (1 << j)
                new_time = dp[mask][i] + dist(crystals[i], crystals[j])
                if new_time < dist(demon, crystals[j]):
                    if new_time < dp[new_mask][j]:
                        dp[new_mask][j] = new_time

    full_mask = (1 << n) - 1
    if any(dp[full_mask][i] < INF for i in range(n)):
        print("Yes")
    else:
        print("No")

solve()
